import { Box, useMediaQuery } from "@mui/material";
import { useEffect, useState } from "react";
import { useSelector } from "react-redux";
import { useParams } from "react-router-dom";
import Navbar from "scenes/navbar";
import FriendListWidget from "scenes/widgets/FriendListWidget";
import MyPostWidget from "scenes/widgets/MyPostWidget";
import PostsWidget from "scenes/widgets/PostsWidget";
import UserWidget from "scenes/widgets/UserWidget";
import { useNavigate } from "react-router-dom";

const ProfilePage = () => {
  const [user, setUser] = useState(null);
  const { userId } = useParams();
  // const [userId, setUserId] = useState(userIdParam);
  const token = useSelector((state) => state.token);
  const posts = useSelector((state) => state.posts);
  const loggedUser = useSelector((state) => state.user);
  const [ searchValue, setSearchValue ] = useState('');
  const isNonMobileScreens = useMediaQuery("(min-width:1000px)");

  // const navigate = useNavigate();
  // navigate(0);
  
  // setUserId(userIdParam);

  console.log("useParam", userId);
  
  const getUser = async () => {
    const response = await fetch(`https://yujins.p-e.kr/users/${userId}`, {
      method: "GET",
      headers: { Authorization: `Bearer ${token}` },
    });
    const data = await response.json();
    setUser(data);
  };

  useEffect(() => {
    getUser();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  if (!user) return null;

  return (
    <Box>
      <Navbar searchValue={setSearchValue}/>
      <Box
        width="100%"
        padding="2rem 6%"
        display={isNonMobileScreens ? "flex" : "block"}
        gap="2rem"
        justifyContent="center"
      >
        <Box flexBasis={isNonMobileScreens ? "26%" : undefined}>
          <UserWidget userId={userId} picturePath={user.picturePath} />
          <Box m="2rem 0" />
          <FriendListWidget userId={userId}/>
        </Box>
        <Box
          flexBasis={isNonMobileScreens ? "42%" : undefined}
          mt={isNonMobileScreens ? undefined : "2rem"}
        >
          { userId==loggedUser._id ? 
            <MyPostWidget picturePath={user.picturePath} isProfile={true}/> 
            : null
          }
         
          <PostsWidget userId={userId} isProfile ={true} searchValue = {searchValue}/>
        </Box>
      </Box>
    </Box>
  );
};

export default ProfilePage;
